mapper.insert:
MERGE INTO ST_WDWV_R t USING (
SELECT #{pojo.STCD} AS STCD, TO_DATE(#{pojo.TM}, 'YYYY-MM-DD HH24:MI:SS') AS TM, #{pojo.WNDV} AS WNDV, #{pojo.WNDPWR} AS WNDPWR, #{pojo.WNDDIR} AS WNDDIR, #{pojo.WNANGLE} AS WNANGLE, #{pojo.PRESSURE} AS PRESSURE FROM DUAL
) s ON (t.STCD = s.STCD AND t.TM = s.TM) WHEN MATCHED THEN UPDATE SET t.WNDV = s.WNDV, t.WNDPWR = s.WNDPWR, t.WNDDIR = s.WNDDIR, t.WNANGLE = s.WNANGLE, t.PRESSURE = s.PRESSURE WHEN NOT MATCHED THEN INSERT (STCD, TM, WNDV, WNDPWR, WNDDIR, WNANGLE, PRESSURE) VALUES (s.STCD, s.TM, s.WNDV, s.WNDPWR, s.WNDDIR, s.WNANGLE, s.PRESSURE)
